-- -----------------------------------------------------------------------------
-- 0. INICIO DE COMPILACIÓN Y HORA OFICIAL DE BOGOTÁ, COLOMBIA (UTC-5)
-- -----------------------------------------------------------------------------
DECLARE
    v_fecha_bogota VARCHAR2(50);
BEGIN
    SELECT TO_CHAR(CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE), 'YYYY-MM-DD HH24:MI:SS')
      INTO v_fecha_bogota
      FROM DUAL;
    DBMS_OUTPUT.PUT_LINE('============================================================================');
    DBMS_OUTPUT.PUT_LINE('  INICIANDO COMPILACIÓN COMPLETA DE OBJETOS PL/SQL - SAMANYA OS');
    DBMS_OUTPUT.PUT_LINE('  TOTAL OBJETOS A COMPILAR: 92');
    DBMS_OUTPUT.PUT_LINE('  HORA OFICIAL (Bogotá, Colombia - UTC-5): ' || v_fecha_bogota);
    DBMS_OUTPUT.PUT_LINE('============================================================================');
END;
/

