CREATE OR REPLACE PACKAGE BODY PKGSMY_ACUDIENTES_DAO
AS
    /*
    || =========================================================================
    || Paquete: PKGSMY_ACUDIENTES_DAO (Body)
    || Propósito: Implementación de operaciones CRUD para SMY_ACUDIENTES
    || Reglas: Sin COMMIT/ROLLBACK, sin lógica de negocio, manejo nativo de JSON
    || =========================================================================
    */

    -- 1. Insertar
    PROCEDURE p_insertar (
        pro_smy_acudientes IN smy_acudientes%ROWTYPE
    )
    IS
    BEGIN
        INSERT INTO smy_acudientes VALUES pro_smy_acudientes;
    END p_insertar;

    -- 2. Traer por PK
    FUNCTION f_traer (
        pty_id IN smy_acudientes.id%TYPE
    ) RETURN smy_acudientes%ROWTYPE
    IS
        v_registro smy_acudientes%ROWTYPE;
    BEGIN
        SELECT *
          INTO v_registro
          FROM smy_acudientes
         WHERE id = pty_id;

        RETURN v_registro;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_traer;

    -- 3. Consultar todos los registros
    PROCEDURE p_consultar_registros (
        pta_smy_acudientes OUT PKGSMY_ACUDIENTES_DAO.ta_smy_acudientes
    )
    IS
    BEGIN
        SELECT *
          BULK COLLECT INTO pta_smy_acudientes
          FROM smy_acudientes;
    END p_consultar_registros;

    -- 4. Eliminar por ROWID
    PROCEDURE p_eliminar_rowid (
        p_rowid IN VARCHAR2
    )
    IS
    BEGIN
        DELETE FROM smy_acudientes
         WHERE ROWID = CHARTOROWID(p_rowid);
    END p_eliminar_rowid;

    -- 5. Eliminar por PK
    PROCEDURE p_eliminar (
        pty_id IN smy_acudientes.id%TYPE
    )
    IS
    BEGIN
        DELETE FROM smy_acudientes
         WHERE id = pty_id;
    END p_eliminar;

    -- 6. Eliminar todos los registros
    PROCEDURE p_eliminar_registros
    IS
    BEGIN
        DELETE FROM smy_acudientes;
    END p_eliminar_registros;

    -- 7. Verificar existencia por PK
    FUNCTION f_existe (
        pty_id IN smy_acudientes.id%TYPE
    ) RETURN BOOLEAN
    IS
        v_dummy NUMBER;
    BEGIN
        SELECT 1
          INTO v_dummy
          FROM smy_acudientes
         WHERE id = pty_id;

        RETURN TRUE;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN FALSE;
    END f_existe;

    -- 8. Verificar existencia y retornar registro
    FUNCTION f_existe (
        pty_id       IN  smy_acudientes.id%TYPE,
        pro_smy_acudientes  OUT smy_acudientes%ROWTYPE
    ) RETURN BOOLEAN
    IS
    BEGIN
        SELECT *
          INTO pro_smy_acudientes
          FROM smy_acudientes
         WHERE id = pty_id;

        RETURN TRUE;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN FALSE;
    END f_existe;

    -- 9. Verificar existencia, retornar registro y ROWID
    FUNCTION f_existe (
        pty_id       IN  smy_acudientes.id%TYPE,
        pro_smy_acudientes  OUT smy_acudientes%ROWTYPE,
        p_rowid      OUT VARCHAR2
    ) RETURN BOOLEAN
    IS
    BEGIN
        SELECT ROWIDTOCHAR(ROWID)
          INTO p_rowid
          FROM smy_acudientes
         WHERE id = pty_id;

        SELECT *
          INTO pro_smy_acudientes
          FROM smy_acudientes
         WHERE ROWID = CHARTOROWID(p_rowid);

        RETURN TRUE;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN FALSE;
    END f_existe;

    -- 10. Verificar existencia por ROWID
    FUNCTION f_existe_rowid (
        p_rowid IN VARCHAR2
    ) RETURN BOOLEAN
    IS
        v_dummy NUMBER;
    BEGIN
        SELECT 1
          INTO v_dummy
          FROM smy_acudientes
         WHERE ROWID = CHARTOROWID(p_rowid);

        RETURN TRUE;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN FALSE;
    END f_existe_rowid;

    -- 11. Verificar existencia por ROWID y retornar registro
    FUNCTION f_existe_rowid (
        p_rowid      IN  VARCHAR2,
        pro_smy_acudientes  OUT smy_acudientes%ROWTYPE
    ) RETURN BOOLEAN
    IS
    BEGIN
        SELECT *
          INTO pro_smy_acudientes
          FROM smy_acudientes
         WHERE ROWID = CHARTOROWID(p_rowid);

        RETURN TRUE;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN FALSE;
    END f_existe_rowid;

    -- 12. Actualizar por registro
    PROCEDURE p_actualizar (
        pro_smy_acudientes IN smy_acudientes%ROWTYPE
    )
    IS
    BEGIN
        UPDATE smy_acudientes
           SET ROW = pro_smy_acudientes
         WHERE id = pro_smy_acudientes.id;
    END p_actualizar;

    -- 13. Actualizar indicando PK
    PROCEDURE p_actualizar (
        pro_smy_acudientes IN smy_acudientes%ROWTYPE,
        pty_id      IN smy_acudientes.id%TYPE
    )
    IS
    BEGIN
        UPDATE smy_acudientes
           SET ROW = pro_smy_acudientes
         WHERE id = pty_id;
    END p_actualizar;

    -- 14. Actualizar por ROWID
    PROCEDURE p_actualizar_rowid (
        pro_smy_acudientes IN smy_acudientes%ROWTYPE,
        p_rowid     IN VARCHAR2
    )
    IS
    BEGIN
        UPDATE smy_acudientes
           SET ROW = pro_smy_acudientes
         WHERE ROWID = CHARTOROWID(p_rowid);
    END p_actualizar_rowid;

    -- 15. Actualizar todos los registros
    PROCEDURE p_actualizar_registros (
        pro_smy_acudientes IN smy_acudientes%ROWTYPE
    )
    IS
    BEGIN
        UPDATE smy_acudientes
           SET ROW = pro_smy_acudientes;
    END p_actualizar_registros;

    -- 16. Obtener valores por defecto
    PROCEDURE p_valores_defecto (
        pro_smy_acudientes IN OUT smy_acudientes%ROWTYPE
    )
    IS
    BEGIN
        pro_smy_acudientes.fecha_creacion := NVL(pro_smy_acudientes.fecha_creacion, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE));
    END p_valores_defecto;

    -- 17. Verificar existencia y retornar JSON
    FUNCTION f_existe_json (
        p_id            IN  smy_acudientes.id%TYPE,
        p_json_smy_acudientes  OUT CLOB
    ) RETURN NUMBER
    IS
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'id_usuario' VALUE t.id_usuario,
                   'id_tipo_identificacion' VALUE t.id_tipo_identificacion,
                   'identificacion' VALUE t.identificacion,
                   'nombres' VALUE t.nombres,
                   'apellidos' VALUE t.apellidos,
                   'telefono_principal' VALUE t.telefono_principal,
                   'telefono_secundario' VALUE t.telefono_secundario,
                   'email' VALUE t.email,
                   'direccion' VALUE t.direccion,
                   'ciudad' VALUE t.ciudad,
                   'id_canal_notif_pref' VALUE t.id_canal_notif_pref,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO p_json_smy_acudientes
          FROM smy_acudientes t
         WHERE t.id = p_id;

        RETURN 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_json_smy_acudientes := NULL;
            RETURN 0;
    END f_existe_json;

    -- 18. Obtener JSON por PK (Retorna CLOB nativo)
    FUNCTION f_json (
        p_id IN smy_acudientes.id%TYPE
    ) RETURN CLOB
    IS
        v_json CLOB;
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'id_usuario' VALUE t.id_usuario,
                   'id_tipo_identificacion' VALUE t.id_tipo_identificacion,
                   'identificacion' VALUE t.identificacion,
                   'nombres' VALUE t.nombres,
                   'apellidos' VALUE t.apellidos,
                   'telefono_principal' VALUE t.telefono_principal,
                   'telefono_secundario' VALUE t.telefono_secundario,
                   'email' VALUE t.email,
                   'direccion' VALUE t.direccion,
                   'ciudad' VALUE t.ciudad,
                   'id_canal_notif_pref' VALUE t.id_canal_notif_pref,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO v_json
          FROM smy_acudientes t
         WHERE t.id = p_id;

        RETURN v_json;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_json;

END PKGSMY_ACUDIENTES_DAO;
/

