        pro_smy_clases_archivos IN OUT smy_clases_archivos%ROWTYPE
    )
    IS
    BEGIN
        pro_smy_clases_archivos.tamano_maximo_mb := NVL(pro_smy_clases_archivos.tamano_maximo_mb, 25);
        pro_smy_clases_archivos.fecha_creacion := NVL(pro_smy_clases_archivos.fecha_creacion, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE));
    END p_valores_defecto;

