    FUNCTION f_existe_json (
        p_id            IN  smy_clases_archivos.id%TYPE,
        p_json_smy_clases_archivos  OUT CLOB
    ) RETURN NUMBER
    IS
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'codigo_clase' VALUE t.codigo_clase,
                   'nombre_clase' VALUE t.nombre_clase,
                   'patron_directorio' VALUE t.patron_directorio,
                   'extensiones_permitidas' VALUE t.extensiones_permitidas,
                   'tamano_maximo_mb' VALUE t.tamano_maximo_mb,
                   'descripcion' VALUE t.descripcion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO p_json_smy_clases_archivos
          FROM smy_clases_archivos t
         WHERE t.id = p_id;

        RETURN 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_json_smy_clases_archivos := NULL;
            RETURN 0;
    END f_existe_json;

    -- 18. Obtener JSON por PK (Retorna CLOB nativo)
    FUNCTION f_json (
        p_id IN smy_clases_archivos.id%TYPE
    ) RETURN CLOB
    IS
        v_json CLOB;
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'codigo_clase' VALUE t.codigo_clase,
                   'nombre_clase' VALUE t.nombre_clase,
                   'patron_directorio' VALUE t.patron_directorio,
                   'extensiones_permitidas' VALUE t.extensiones_permitidas,
                   'tamano_maximo_mb' VALUE t.tamano_maximo_mb,
                   'descripcion' VALUE t.descripcion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO v_json
          FROM smy_clases_archivos t
         WHERE t.id = p_id;

        RETURN v_json;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_json;

END PKGSMY_CLASES_ARCHIVOS_DAO;
