    || Reglas: Sin COMMIT/ROLLBACK, sin lógica de negocio, manejo nativo de JSON
    || =========================================================================
    */

    -- 1. Insertar
    PROCEDURE p_insertar (
        pro_smy_estados_archivos IN smy_estados_archivos%ROWTYPE
    )
    IS
    BEGIN
        INSERT INTO smy_estados_archivos VALUES pro_smy_estados_archivos;
    END p_insertar;

    -- 2. Traer por PK
    FUNCTION f_traer (
        pty_id IN smy_estados_archivos.id%TYPE
    ) RETURN smy_estados_archivos%ROWTYPE
    IS
        v_registro smy_estados_archivos%ROWTYPE;
    BEGIN
        SELECT *
          INTO v_registro
          FROM smy_estados_archivos
         WHERE id = pty_id;

        RETURN v_registro;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_traer;

    -- 3. Consultar todos los registros
    PROCEDURE p_consultar_registros (
        pta_smy_estados_archivos OUT PKGSMY_ESTADOS_ARCHIVOS_DAO.ta_smy_estados_archivos
    )
    IS
    BEGIN
        SELECT *
          BULK COLLECT INTO pta_smy_estados_archivos
          FROM smy_estados_archivos;
    END p_consultar_registros;

    -- 4. Eliminar por ROWID
    PROCEDURE p_eliminar_rowid (
        p_rowid IN VARCHAR2
    )
    IS
    BEGIN
        DELETE FROM smy_estados_archivos
         WHERE ROWID = CHARTOROWID(p_rowid);
    END p_eliminar_rowid;

    -- 5. Eliminar por PK
    PROCEDURE p_eliminar (
        pty_id IN smy_estados_archivos.id%TYPE
