    ) RETURN BOOLEAN
    IS
    BEGIN
        SELECT ROWIDTOCHAR(ROWID)
          INTO p_rowid
          FROM smy_estados_archivos
         WHERE id = pty_id;

        SELECT *
          INTO pro_smy_estados_archivos
          FROM smy_estados_archivos
         WHERE ROWID = CHARTOROWID(p_rowid);

        RETURN TRUE;
