    -- 12. Actualizar por registro
    PROCEDURE p_actualizar (
        pro_smy_estados_archivos IN smy_estados_archivos%ROWTYPE
    )
    IS
    BEGIN
        UPDATE smy_estados_archivos
           SET ROW = pro_smy_estados_archivos
         WHERE id = pro_smy_estados_archivos.id;
    END p_actualizar;

    -- 13. Actualizar indicando PK
    PROCEDURE p_actualizar (
        pro_smy_estados_archivos IN smy_estados_archivos%ROWTYPE,
        pty_id      IN smy_estados_archivos.id%TYPE
    )
    IS
    BEGIN
        UPDATE smy_estados_archivos
           SET ROW = pro_smy_estados_archivos
         WHERE id = pty_id;
    END p_actualizar;

    -- 14. Actualizar por ROWID
    PROCEDURE p_actualizar_rowid (
        pro_smy_estados_archivos IN smy_estados_archivos%ROWTYPE,
        p_rowid     IN VARCHAR2
    )
    IS
    BEGIN
        UPDATE smy_estados_archivos
           SET ROW = pro_smy_estados_archivos
         WHERE ROWID = CHARTOROWID(p_rowid);
    END p_actualizar_rowid;

    -- 15. Actualizar todos los registros
    PROCEDURE p_actualizar_registros (
        pro_smy_estados_archivos IN smy_estados_archivos%ROWTYPE
    )
    IS
    BEGIN
        UPDATE smy_estados_archivos
           SET ROW = pro_smy_estados_archivos;
    END p_actualizar_registros;

    -- 16. Obtener valores por defecto
    PROCEDURE p_valores_defecto (
        pro_smy_estados_archivos IN OUT smy_estados_archivos%ROWTYPE
    )
    IS
    BEGIN
        pro_smy_estados_archivos.fecha_creacion := NVL(pro_smy_estados_archivos.fecha_creacion, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE));
    END p_valores_defecto;

    -- 17. Verificar existencia y retornar JSON
    FUNCTION f_existe_json (
        p_id            IN  smy_estados_archivos.id%TYPE,
        p_json_smy_estados_archivos  OUT CLOB
    ) RETURN NUMBER
    IS
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'nombre_estado_archivo' VALUE t.nombre_estado_archivo,
                   'descripcion' VALUE t.descripcion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO p_json_smy_estados_archivos
          FROM smy_estados_archivos t
         WHERE t.id = p_id;

        RETURN 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_json_smy_estados_archivos := NULL;
            RETURN 0;
    END f_existe_json;

    -- 18. Obtener JSON por PK (Retorna CLOB nativo)
    FUNCTION f_json (
        p_id IN smy_estados_archivos.id%TYPE
    ) RETURN CLOB
    IS
        v_json CLOB;
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'nombre_estado_archivo' VALUE t.nombre_estado_archivo,
                   'descripcion' VALUE t.descripcion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO v_json
          FROM smy_estados_archivos t
         WHERE t.id = p_id;

        RETURN v_json;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_json;

END PKGSMY_ESTADOS_ARCHIVOS_DAO;
/

