                   'id' VALUE t.id,
                   'nombre_estado_permiso' VALUE t.nombre_estado_permiso,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
