    ) RETURN BOOLEAN
    IS
    BEGIN
        SELECT ROWIDTOCHAR(ROWID)
          INTO p_rowid
          FROM smy_roles
         WHERE id = pty_id;

        SELECT *
          INTO pro_smy_roles
          FROM smy_roles
         WHERE ROWID = CHARTOROWID(p_rowid);

