    -- 16. Obtener valores por defecto
    PROCEDURE p_valores_defecto (
        pro_smy_roles IN OUT smy_roles%ROWTYPE
    )
    IS
    BEGIN
        pro_smy_roles.fecha_creacion := NVL(pro_smy_roles.fecha_creacion, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE));
        -- pro_smy_roles.id_estado_rol := NVL(pro_smy_roles.id_estado_rol, 1);
    END p_valores_defecto;

    -- 17. Verificar existencia y retornar JSON
    FUNCTION f_existe_json (
        p_id            IN  smy_roles.id%TYPE,
        p_json_smy_roles  OUT CLOB
    ) RETURN NUMBER
    IS
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'codigo' VALUE t.codigo,
                   'nombre' VALUE t.nombre,
                   'descripcion' VALUE t.descripcion,
                   'id_estado_rol' VALUE t.id_estado_rol,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO p_json_smy_roles
          FROM smy_roles t
         WHERE t.id = p_id;

        RETURN 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_json_smy_roles := NULL;
            RETURN 0;
    END f_existe_json;

    -- 18. Obtener JSON por PK (Retorna CLOB nativo)
    FUNCTION f_json (
        p_id IN smy_roles.id%TYPE
    ) RETURN CLOB
    IS
        v_json CLOB;
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'codigo' VALUE t.codigo,
                   'nombre' VALUE t.nombre,
                   'descripcion' VALUE t.descripcion,
                   'id_estado_rol' VALUE t.id_estado_rol,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO v_json
          FROM smy_roles t
         WHERE t.id = p_id;

        RETURN v_json;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_json;

END PKGSMY_ROLES_DAO;
