           SET ROW = pro_smy_vias_administracion;
    END p_actualizar_registros;

    -- 16. Obtener valores por defecto
    PROCEDURE p_valores_defecto (
        pro_smy_vias_administracion IN OUT smy_vias_administracion%ROWTYPE
    )
    IS
    BEGIN
        pro_smy_vias_administracion.fecha_creacion := NVL(pro_smy_vias_administracion.fecha_creacion, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE));
    END p_valores_defecto;

    -- 17. Verificar existencia y retornar JSON
    FUNCTION f_existe_json (
        p_id            IN  smy_vias_administracion.id%TYPE,
        p_json_smy_vias_administracion  OUT CLOB
    ) RETURN NUMBER
    IS
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'nombre_via_administracion' VALUE t.nombre_via_administracion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO p_json_smy_vias_administracion
          FROM smy_vias_administracion t
         WHERE t.id = p_id;

        RETURN 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            p_json_smy_vias_administracion := NULL;
            RETURN 0;
    END f_existe_json;

    -- 18. Obtener JSON por PK (Retorna CLOB nativo)
    FUNCTION f_json (
        p_id IN smy_vias_administracion.id%TYPE
    ) RETURN CLOB
    IS
        v_json CLOB;
    BEGIN
        SELECT JSON_OBJECT(
                   'id' VALUE t.id,
                   'nombre_via_administracion' VALUE t.nombre_via_administracion,
                   'fecha_creacion' VALUE TO_CHAR(t.fecha_creacion, 'YYYY-MM-DD"T"HH24:MI:SS'),
                   'id_usuario_ultima_modificacion' VALUE t.id_usuario_ultima_modificacion
                   RETURNING CLOB
               )
          INTO v_json
          FROM smy_vias_administracion t
         WHERE t.id = p_id;

        RETURN v_json;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_json;

END PKGSMY_VIAS_ADMINISTRACION_DAO;
/

-- =============================================================================
-- OBJETO [88/92]: F_FECHA_ACTUAL
-- ARCHIVO FUENTE: f_fecha_actual.sql
-- =============================================================================
CREATE OR REPLACE FUNCTION f_fecha_actual
    RETURN DATE
IS
    l_date      date;
BEGIN
    SELECT (SYSTIMESTAMP AT TIME ZONE 'America/Bogota') INTO l_date
      FROM DUAL;
    RETURN l_date;
END f_fecha_actual;
/

-- =============================================================================
-- OBJETO [89/92]: UTI_GE_EXCEPCIONES_PKG
-- ARCHIVO FUENTE: uti_ge_excepciones_pkg.sql
-- =============================================================================
CREATE OR REPLACE PACKAGE uti_ge_excepciones_pkg 
AS
    PROCEDURE p_grabar_log (pro_smy_errores IN OUT smy_errores%ROWTYPE);
END uti_ge_excepciones_pkg;
/
CREATE OR REPLACE PACKAGE BODY uti_ge_excepciones_pkg 
AS
    PROCEDURE p_grabar_log (pro_smy_errores IN OUT smy_errores%ROWTYPE)
    AS
        PRAGMA AUTONOMOUS_TRANSACTION;
    BEGIN
        pro_smy_errores := pro_smy_errores;
        -- Valores por defecto
        pro_smy_errores.id := smy_errores_seq.nextval;
        pro_smy_errores.fecha_creacion := f_fecha_actual;
        pro_smy_errores.codigo_error := SQLCODE;
        pro_smy_errores.texto_error := SUBSTR (SQLERRM, 1, 3999);
        pro_smy_errores.mensaje_error := DBMS_UTILITY.format_error_backtrace ();

        IF pro_smy_errores.tipo IS NULL
        THEN
            pro_smy_errores.tipo := 'E';
        END IF;

        IF pro_smy_errores.usuario IS NULL
        THEN
            pro_smy_errores.usuario := USER;
        END IF;

        pkgsmy_errores_dao.p_insertar (pro_smy_errores);
        COMMIT;
    END p_grabar_log;
END uti_ge_excepciones_pkg;
/

-- =============================================================================
-- OBJETO [90/92]: PKGCA_RESIDENTES
-- ARCHIVO FUENTE: pkgca_residentes.sql
-- =============================================================================
-- =============================================================================
-- ESPECIFICACIÓN Y CUERPO: PKGCA_RESIDENTES
-- FAMILIA: pkgca_ (Consultas avanzadas, filtros multi-criterio, SYS_REFCURSOR y JSON nativo)
-- ESTÁNDAR ARQUITECTÓNICO: oracle-plsql-architecture
-- =============================================================================

CREATE OR REPLACE PACKAGE PKGCA_RESIDENTES
AS
    /**
     * Retorna cursor multi-fila con censo de residentes activos filtrados por habitación o estado
     */
    PROCEDURE p_consultar_censo (
        p_id_estado        IN  smy_residentes.id_estado_residente%TYPE DEFAULT NULL,
        p_filtro_texto     IN  VARCHAR2 DEFAULT NULL,
        p_cursor           OUT SYS_REFCURSOR
    );

    /**
     * Retorna detalle clínico y general de un residente en formato JSON nativo (CLOB)
     * Utiliza JSON_OBJECT / JSON_ARRAYAGG RETURNING CLOB sin concatenación de cadenas.
     */
    FUNCTION f_obtener_ficha_json (
        p_id_residente     IN  smy_residentes.id%TYPE
    ) RETURN CLOB;

END PKGCA_RESIDENTES;
/

CREATE OR REPLACE PACKAGE BODY PKGCA_RESIDENTES
AS

    PROCEDURE p_consultar_censo (
        p_id_estado        IN  smy_residentes.id_estado_residente%TYPE DEFAULT NULL,
        p_filtro_texto     IN  VARCHAR2 DEFAULT NULL,
        p_cursor           OUT SYS_REFCURSOR
    ) IS
    BEGIN
        OPEN p_cursor FOR
            SELECT 
                r.id,
                r.codigo_expediente,
                r.identificacion,
                r.nombres,
                r.apellidos,
                r.nombres || ' ' || r.apellidos AS nombre_completo,
                TRUNC(MONTHS_BETWEEN(SYSDATE, r.fecha_nacimiento) / 12) AS edad,
                r.habitacion,
                r.cama,
                r.foto_url,
                m.nombre_nivel_movilidad AS nivel_movilidad,
                d.nombre_tipo_dieta AS tipo_dieta,
                r.alertas_clinicas,
                e.nombre_estado_residente AS estado
            FROM smy_residentes r
            INNER JOIN smy_estados_residentes e ON r.id_estado_residente = e.id
            LEFT JOIN smy_niveles_movilidad m ON r.id_nivel_movilidad = m.id
            LEFT JOIN smy_tipos_dietas d ON r.id_tipo_dieta = d.id
            WHERE (p_id_estado IS NULL OR r.id_estado_residente = p_id_estado)
              AND (p_filtro_texto IS NULL OR (
                    UPPER(r.nombres) LIKE '%' || UPPER(p_filtro_texto) || '%' OR
                    UPPER(r.apellidos) LIKE '%' || UPPER(p_filtro_texto) || '%' OR
                    UPPER(r.habitacion) LIKE '%' || UPPER(p_filtro_texto) || '%' OR
                    UPPER(r.cama) LIKE '%' || UPPER(p_filtro_texto) || '%'
                  ))
            ORDER BY r.habitacion, r.cama;
    END p_consultar_censo;

    FUNCTION f_obtener_ficha_json (
        p_id_residente     IN  smy_residentes.id%TYPE
    ) RETURN CLOB IS
        vcl_resultado CLOB;
    BEGIN
        SELECT JSON_OBJECT(
            'id'                  VALUE r.id,
            'codigoExpediente'    VALUE r.codigo_expediente,
            'identificacion'      VALUE r.identificacion,
            'nombres'             VALUE r.nombres,
            'apellidos'           VALUE r.apellidos,
            'nombreCompleto'      VALUE r.nombres || ' ' || r.apellidos,
            'edad'                VALUE TRUNC(MONTHS_BETWEEN(SYSDATE, r.fecha_nacimiento) / 12),
            'fechaNacimiento'     VALUE TO_CHAR(r.fecha_nacimiento, 'YYYY-MM-DD'),
            'habitacion'          VALUE r.habitacion,
            'cama'                VALUE r.cama,
            'fotoUrl'             VALUE r.foto_url,
            'eps'                 VALUE r.eps,
            'planComplementario'  VALUE r.plan_complementario,
            'tipoSangre'          VALUE r.tipo_sangre,
            'movilidad'           VALUE m.nombre_nivel_movilidad,
            'dieta'               VALUE d.nombre_tipo_dieta,
            'alertasClinicas'     VALUE r.alertas_clinicas,
            'estado'              VALUE e.nombre_estado_residente,
            'fechaIngreso'        VALUE TO_CHAR(r.fecha_ingreso, 'YYYY-MM-DD'),
            'responsables'        VALUE (
                SELECT JSON_ARRAYAGG(
                    JSON_OBJECT(
                        'id'            VALUE a.id,
                        'nombres'       VALUE a.nombres,
                        'apellidos'     VALUE a.apellidos,
                        'parentesco'    VALUE p.nombre_parentesco,
                        'telefono'      VALUE a.telefono_principal,
                        'email'         VALUE a.email
                    ) RETURNING CLOB
                )
                FROM smy_residente_acudiente ra
                INNER JOIN smy_acudientes a ON ra.id_acudiente = a.id
                INNER JOIN smy_parentescos p ON ra.id_parentesco = p.id
                WHERE ra.id_residente = r.id
            )
            RETURNING CLOB
        )
        INTO vcl_resultado
        FROM smy_residentes r
        INNER JOIN smy_estados_residentes e ON r.id_estado_residente = e.id
        LEFT JOIN smy_niveles_movilidad m ON r.id_nivel_movilidad = m.id
        LEFT JOIN smy_tipos_dietas d ON r.id_tipo_dieta = d.id
        WHERE r.id = p_id_residente;

        RETURN vcl_resultado;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
            RETURN NULL;
    END f_obtener_ficha_json;

END PKGCA_RESIDENTES;
/

-- =============================================================================
-- OBJETO [91/92]: PKGCN_AUTH
-- ARCHIVO FUENTE: pkgcn_auth.sql
-- =============================================================================
-- =============================================================================
-- ESPECIFICACIÓN Y CUERPO OFICIAL PKGCN: PKGCN_AUTH
-- ESTÁNDAR ARQUITECTÓNICO: oracle-plsql-architecture
-- =============================================================================

CREATE OR REPLACE PACKAGE PKGCN_AUTH
AS
    -- Autenticación y registro de acceso
    PROCEDURE pr_autenticar (
        p_usuario_o_email   IN VARCHAR2,
        p_direccion_ip      IN VARCHAR2,
        p_dispositivo_info  IN VARCHAR2,
        p_cursor_usuario    OUT SYS_REFCURSOR
    );

    -- Registro y actualización de token push para dispositivos móviles
    PROCEDURE pr_registrar_dispositivo_push (
        p_id_usuario        IN smy_usuarios.id%TYPE,
        p_token_dispositivo IN smy_dispositivos_push.token_dispositivo%TYPE,
        p_plataforma        IN smy_dispositivos_push.plataforma%TYPE
    );

    -- Desactivación de token push al cerrar sesión
    PROCEDURE pr_desactivar_dispositivo_push (
        p_id_usuario        IN smy_usuarios.id%TYPE,
        p_token_dispositivo IN smy_dispositivos_push.token_dispositivo%TYPE
    );

END PKGCN_AUTH;
/

CREATE OR REPLACE PACKAGE BODY PKGCN_AUTH
AS
    vro_error smy_errores%ROWTYPE;

    PROCEDURE pr_autenticar (
        p_usuario_o_email   IN VARCHAR2,
        p_direccion_ip      IN VARCHAR2,
        p_dispositivo_info  IN VARCHAR2,
        p_cursor_usuario    OUT SYS_REFCURSOR
    ) IS
        l_id_usuario smy_usuarios.id%TYPE;
    BEGIN
        -- Buscar ID de usuario
        BEGIN
            SELECT id
              INTO l_id_usuario
              FROM smy_usuarios
             WHERE (LOWER(username) = LOWER(p_usuario_o_email) OR LOWER(email) = LOWER(p_usuario_o_email))
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                -- Registrar intento fallido
                BEGIN
                    INSERT INTO smy_auditoria_accesos (
                        id_usuario, accion, direccion_ip, detalles, fecha_creacion
                    ) VALUES (
                        NULL, 'LOGIN_FALLIDO', SUBSTR(p_direccion_ip, 1, 45),
                        'Dispositivo: ' || SUBSTR(p_dispositivo_info, 1, 200) || ' | Identificador: ' || p_usuario_o_email || ' | Motivo: Usuario o correo no encontrado',
                        CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE)
                    );
                    COMMIT;
                EXCEPTION
                    WHEN OTHERS THEN
                        NULL; -- Manejo defensivo en caso de que ID_USUARIO tenga restricción NOT NULL
                END;
                RAISE_APPLICATION_ERROR(-20001, 'Credenciales inválidas');
        END;

        -- Actualizar último acceso del usuario
        UPDATE smy_usuarios
           SET ultimo_acceso = CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE)
         WHERE id = l_id_usuario;

        -- Registrar acceso exitoso
        INSERT INTO smy_auditoria_accesos (
            id_usuario, accion, direccion_ip, detalles, fecha_creacion
        ) VALUES (
            l_id_usuario, 'LOGIN_EXITOSO', SUBSTR(p_direccion_ip, 1, 45),
            'Dispositivo: ' || SUBSTR(p_dispositivo_info, 1, 200) || ' | Autenticación exitosa',
            CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE)
        );

        -- Retornar datos completos vía SYS_REFCURSOR
        OPEN p_cursor_usuario FOR
            SELECT u.id,
                   u.username,
                   u.email,
                   u.password_hash,
                   u.nombre_completo,
                   u.telefono,
                   u.avatar_url,
                   u.id_estado_usuario,
                   r.codigo AS codigo_rol,
                   r.nombre AS nombre_rol,
                   e.nombre_estado_usuario
              FROM smy_usuarios u
              JOIN smy_roles r ON r.id = u.id_rol
              JOIN smy_estados_usuarios e ON e.id = u.id_estado_usuario
             WHERE u.id = l_id_usuario;

        COMMIT;

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            IF SQLCODE BETWEEN -20999 AND -20001 THEN
                RAISE;
            END IF;
            vro_error.nombre_programa := 'PKGCN_AUTH';
            vro_error.nombre_metodo   := 'PR_AUTENTICAR';
            vro_error.parametros      := 'p_usuario_o_email: ' || p_usuario_o_email || CHR(10) ||
                                         'p_direccion_ip: ' || p_direccion_ip;
            uti_ge_excepciones_pkg.p_grabar_log(vro_error);
            RAISE_APPLICATION_ERROR(-20000, 'Se presento un error comunicarse con soporte. Número error: ' || vro_error.id || ' - ' || SQLERRM);
    END pr_autenticar;

    PROCEDURE pr_registrar_dispositivo_push (
        p_id_usuario        IN smy_usuarios.id%TYPE,
        p_token_dispositivo IN smy_dispositivos_push.token_dispositivo%TYPE,
        p_plataforma        IN smy_dispositivos_push.plataforma%TYPE
    ) IS
    BEGIN
        MERGE INTO smy_dispositivos_push d
        USING (SELECT p_id_usuario AS id_usuario, p_token_dispositivo AS token_dispositivo, p_plataforma AS plataforma FROM DUAL) s
        ON (d.token_dispositivo = s.token_dispositivo)
        WHEN MATCHED THEN
            UPDATE SET d.id_usuario                     = s.id_usuario,
                       d.plataforma                     = s.plataforma,
                       d.activo                         = 'S',
                       d.fecha_ultimo_uso               = CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE),
                       d.id_usuario_ultima_modificacion = s.id_usuario
        WHEN NOT MATCHED THEN
            INSERT (
                id_usuario, token_dispositivo, plataforma, fecha_ultimo_uso, activo, fecha_creacion, id_usuario_ultima_modificacion
            ) VALUES (
                s.id_usuario, s.token_dispositivo, s.plataforma, CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE),
                'S', CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE), s.id_usuario
            );

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            vro_error.nombre_programa := 'PKGCN_AUTH';
            vro_error.nombre_metodo   := 'PR_REGISTRAR_DISPOSITIVO_PUSH';
            vro_error.parametros      := 'p_id_usuario: ' || p_id_usuario || CHR(10) ||
                                         'p_plataforma: ' || p_plataforma;
            uti_ge_excepciones_pkg.p_grabar_log(vro_error);
            RAISE_APPLICATION_ERROR(-20000, 'Se presento un error comunicarse con soporte. Número error: ' || vro_error.id || ' - ' || SQLERRM);
    END pr_registrar_dispositivo_push;

    PROCEDURE pr_desactivar_dispositivo_push (
        p_id_usuario        IN smy_usuarios.id%TYPE,
        p_token_dispositivo IN smy_dispositivos_push.token_dispositivo%TYPE
    ) IS
    BEGIN
        UPDATE smy_dispositivos_push
           SET activo = 'N',
               id_usuario_ultima_modificacion = p_id_usuario
         WHERE token_dispositivo = p_token_dispositivo;

        COMMIT;
    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            vro_error.nombre_programa := 'PKGCN_AUTH';
            vro_error.nombre_metodo   := 'PR_DESACTIVAR_DISPOSITIVO_PUSH';
            vro_error.parametros      := 'p_id_usuario: ' || p_id_usuario;
            uti_ge_excepciones_pkg.p_grabar_log(vro_error);
            RAISE_APPLICATION_ERROR(-20000, 'Se presento un error comunicarse con soporte. Número error: ' || vro_error.id || ' - ' || SQLERRM);
    END pr_desactivar_dispositivo_push;

END PKGCN_AUTH;
/

-- =============================================================================
-- OBJETO [92/92]: PKGCN_CONSENTIMIENTOS
-- ARCHIVO FUENTE: pkgcn_consentimientos.sql
-- =============================================================================
-- =============================================================================
-- ESPECIFICACIÓN Y CUERPO: PKGCN_CONSENTIMIENTOS
-- FAMILIA: pkgcn_ (Transacciones atómicas de negocio, COMMIT/ROLLBACK y logging en SMY_ERRORES)
-- ESTÁNDAR ARQUITECTÓNICO: oracle-plsql-architecture
-- =============================================================================

CREATE OR REPLACE PACKAGE PKGCN_CONSENTIMIENTOS
AS
    /**
     * Registra la firma digital de un acudiente sobre un consentimiento informado,
     * actualizando trazabilidad, sello de tiempo, hash digital y estado global.
     */
    PROCEDURE p_firmar_consentimiento (
        p_id_consentimiento       IN  smy_consentimientos.id%TYPE,
        p_id_acudiente            IN  smy_acudientes.id%TYPE,
        p_ip_firma                IN  VARCHAR2,
        p_firma_canvas_base64     IN  CLOB,
        p_firma_hash              IN  VARCHAR2,
        p_id_usuario_accion       IN  smy_usuarios.id%TYPE,
        p_mensaje_resultado       OUT VARCHAR2
    );

END PKGCN_CONSENTIMIENTOS;
/

CREATE OR REPLACE PACKAGE BODY PKGCN_CONSENTIMIENTOS
AS

    PROCEDURE p_firmar_consentimiento (
        p_id_consentimiento       IN  smy_consentimientos.id%TYPE,
        p_id_acudiente            IN  smy_acudientes.id%TYPE,
        p_ip_firma                IN  VARCHAR2,
        p_firma_canvas_base64     IN  CLOB,
        p_firma_hash              IN  VARCHAR2,
        p_id_usuario_accion       IN  smy_usuarios.id%TYPE,
        p_mensaje_resultado       OUT VARCHAR2
    ) IS
        vn_id_estado_aprobado     NUMBER(10);
        vn_id_estado_firmado_dest NUMBER(10);
        vro_error                 smy_errores%ROWTYPE;
    BEGIN
        -- 1. Validar estado APROBADO en catálogo de consentimientos
        BEGIN
            SELECT id INTO vn_id_estado_aprobado
              FROM smy_estados_consentimientos
             WHERE (UPPER(nombre_estado_consentimiento) LIKE '%APROBADO%'
                 OR UPPER(nombre_estado_consentimiento) LIKE '%FIRMADO%')
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20001, 'No se encontró el estado de consentimiento aprobado en el catálogo.');
        END;

        -- 2. Validar estado FIRMADO en catálogo de firmas de destinatarios
        BEGIN
            SELECT id INTO vn_id_estado_firmado_dest
              FROM smy_estados_firmas_cons
             WHERE (UPPER(nombre_estado_firma_cons) LIKE '%FIRMADO%'
                 OR UPPER(nombre_estado_firma_cons) LIKE '%APROBADO%')
               AND ROWNUM = 1;
        EXCEPTION
            WHEN NO_DATA_FOUND THEN
                RAISE_APPLICATION_ERROR(-20002, 'No se encontró el estado de firma en el catálogo.');
        END;

        -- 3. Actualizar registro del documento de consentimiento
        UPDATE smy_consentimientos
           SET id_estado_consentimiento       = vn_id_estado_aprobado,
               fecha_respuesta                = CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE),
               id_usuario_ultima_modificacion = p_id_usuario_accion
         WHERE id = p_id_consentimiento;

        IF SQL%ROWCOUNT = 0 THEN
            RAISE_APPLICATION_ERROR(-20003, 'El consentimiento indicado no existe en el sistema.');
        END IF;

        -- 4. Actualizar o registrar la firma del destinatario
        UPDATE smy_consentimiento_destinatarios
           SET id_estado_firma_cons           = vn_id_estado_firmado_dest,
               fecha_accion                   = CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE),
               ip_firma                       = p_ip_firma,
               firma_digital_hash             = p_firma_hash,
               firma_canvas_base64            = p_firma_canvas_base64,
               id_usuario_ultima_modificacion = p_id_usuario_accion
         WHERE id_consentimiento = p_id_consentimiento
           AND (p_id_acudiente IS NULL OR id_acudiente = p_id_acudiente);

        -- 5. Control de confirmación transaccional
        COMMIT;

        p_mensaje_resultado := 'Consentimiento firmado y respaldado exitosamente.';

    EXCEPTION
        WHEN OTHERS THEN
            ROLLBACK;
            IF SQLCODE BETWEEN -20999 AND -20001 THEN
                RAISE;
            END IF;
            vro_error.nombre_programa     := 'PKGCN_CONSENTIMIENTOS';
            vro_error.nombre_metodo       := 'P_FIRMAR_CONSENTIMIENTO';
            vro_error.parametros          := 'p_id_consentimiento: ' || p_id_consentimiento || CHR(10) ||
                                             'p_id_acudiente: ' || p_id_acudiente || CHR(10) ||
                                             'p_id_usuario_accion: ' || p_id_usuario_accion;
            vro_error.direccion_ip        := SUBSTR(p_ip_firma, 1, 30);
            vro_error.id_usuario_creacion := p_id_usuario_accion;

            uti_ge_excepciones_pkg.p_grabar_log(vro_error);

            RAISE_APPLICATION_ERROR(-20000, 'Se presento un error comunicarse con soporte. Número error: ' || vro_error.id || ' - ' || SQLERRM);
    END p_firmar_consentimiento;

END PKGCN_CONSENTIMIENTOS;
/

-- =============================================================================
-- 5. VALIDACIÓN DE OBJETOS INVÁLIDOS EN EL ESQUEMA (SI EXISTEN)
-- =============================================================================
DECLARE
    vn_invalidos NUMBER := 0;
BEGIN
    FOR reg IN (
        SELECT object_type, object_name, status
          FROM user_objects
         WHERE status = 'INVALID'
           AND (object_name LIKE 'PKGSMY_%_DAO' 
                OR object_name LIKE 'PKGCA_%' 
                OR object_name LIKE 'PKGCN_%'
                OR object_name = 'UTI_GE_EXCEPCIONES_PKG'
                OR object_name = 'F_FECHA_ACTUAL')
         ORDER BY object_type, object_name
    ) LOOP
        vn_invalidos := vn_invalidos + 1;
        DBMS_OUTPUT.PUT_LINE('  ALERTA: Objeto ' || reg.object_type || ' ' || reg.object_name || ' tiene estado ' || reg.status);
    END LOOP;

    IF vn_invalidos = 0 THEN
        DBMS_OUTPUT.PUT_LINE('============================================================================');
        DBMS_OUTPUT.PUT_LINE('  OK: Todos los 92 objetos PL/SQL se encuentran en estado VALID.');
        DBMS_OUTPUT.PUT_LINE('============================================================================');
    ELSE
        DBMS_OUTPUT.PUT_LINE('============================================================================');
        DBMS_OUTPUT.PUT_LINE('  ATENCIÓN: Se detectaron ' || vn_invalidos || ' objetos en estado INVALID.');
        DBMS_OUTPUT.PUT_LINE('============================================================================');
    END IF;
END;
/

-- =============================================================================
-- 6. RESUMEN FINAL DE COMPILACIÓN
-- =============================================================================
DECLARE
    v_fecha_fin VARCHAR2(50);
BEGIN
    SELECT TO_CHAR(CAST(SYSTIMESTAMP AT TIME ZONE '-05:00' AS DATE), 'YYYY-MM-DD HH24:MI:SS')
      INTO v_fecha_fin
      FROM DUAL;
    DBMS_OUTPUT.PUT_LINE('============================================================================');
    DBMS_OUTPUT.PUT_LINE('  COMPILACIÓN COMPLETADA - HORA BOGOTÁ (UTC-5): ' || v_fecha_fin);
    DBMS_OUTPUT.PUT_LINE('  Total objetos compilados: 92 (87 DAOs + 2 Utilidades + 1 Consulta + 2 Transaccionales)');
    DBMS_OUTPUT.PUT_LINE('============================================================================');
END;
/
